package com.bank.copyadd;

// A build source: a plain file, a local archive, or a remote URL.
public final class Source {
    public enum Kind { FILE, ARCHIVE, URL }
    private final String name;
    private final Kind kind;
    private final boolean verified; // for URLs: did we verify a checksum?

    public Source(String name, Kind kind, boolean verified) {
        this.name = name;
        this.kind = kind;
        this.verified = verified;
    }
    public String getName()   { return name; }
    public Kind getKind()     { return kind; }
    public boolean isVerified(){ return verified; }
}
