package com.bank.copyadd;

import java.util.logging.Logger;

// COPY: places local files EXACTLY as-is. No extraction, no URLs.
public class FileCopier {
    private static final Logger log = Logger.getLogger(FileCopier.class.getName());

    public void copy(Source src, String dest, ImageFs fs) {
        if (src.getKind() == Source.Kind.URL) {
            // COPY cannot fetch URLs.
            log.severe("COPY cannot fetch a URL: " + src.getName() + " (use a verified RUN download)");
            return;
        }
        // Even an archive is placed as the archive file, NOT extracted.
        fs.add(dest + src.getName());
        log.info(() -> "COPY placed '" + src.getName() + "' as-is at " + dest + " (predictable)");
    }
}
