// ─── File: src/main/java/com/bank/copyadd/AddCopier.java ───
package com.bank.copyadd;

import java.util.logging.Logger;

// ADD: auto-extracts local archives and can fetch URLs (less predictable).
public class AddCopier {
    private static final Logger log = Logger.getLogger(AddCopier.class.getName());

    public void add(Source src, String dest, ImageFs fs) {
        switch (src.getKind()) {
            case FILE -> {
                fs.add(dest + src.getName());
                log.info(() -> "ADD placed '" + src.getName() + "' (same as COPY here)");
            }
            case ARCHIVE -> {
                // Surprise: auto-extracts the archive contents.
                fs.add(dest + "extracted/config.yml");
                fs.add(dest + "extracted/certs.pem");
                log.warning(() -> "ADD auto-EXTRACTED '" + src.getName()
                        + "' into " + dest + "extracted/ (not obvious from the line!)");
            }
            case URL -> {
                fs.add(dest + src.getName());
                if (!src.isVerified()) {
                    log.severe("ADD fetched UNVERIFIED url '" + src.getName()
                            + "' -> supply-chain risk");
                }
            }
        }
    }
}
