package com.bank.copyadd;

import java.util.logging.*;

public class CopyVsAddDemo {
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new CopyAddLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Logger log = Logger.getLogger(CopyVsAddDemo.class.getName());
        FileCopier copy = new FileCopier();
        AddCopier add = new AddCopier();

        Source jar     = new Source("transfer-service.jar", Source.Kind.FILE, true);
        Source archive = new Source("config-bundle.tar.gz", Source.Kind.ARCHIVE, true);
        Source url      = new Source("driver.jar", Source.Kind.URL, false);

        log.info("=== Plain JAR: COPY and ADD behave the same ===");
        copy.copy(jar, "/app/", new ImageFs());
        add.add(jar, "/app/", new ImageFs());

        log.info("=== Archive: COPY keeps it, ADD extracts it ===");
        ImageFs copyFs = new ImageFs();
        copy.copy(archive, "/app/config/", copyFs);
        log.info("COPY image fs: " + copyFs.entries());
        ImageFs addFs = new ImageFs();
        add.add(archive, "/app/config/", addFs);
        log.info("ADD image fs:  " + addFs.entries());

        log.info("=== URL: COPY refuses, ADD fetches unverified ===");
        copy.copy(url, "/app/libs/", new ImageFs());
        add.add(url, "/app/libs/", new ImageFs());

        log.info("Preferred: COPY for local files; verified RUN download for remote");
    }
}

// ─── Would be in CopyAddLogFormatter.java in a real project ───
class CopyAddLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
