 && echo "a1b2c3...expected-sha256  /app/driver.jar" | sha256sum -c -

# ADD is only justified for deliberate local archive extraction:
# ADD config-bundle.tar.gz /app/config/   # auto-extracts - use ONLY when intended

ENTRYPOINT ["java","-jar","/app/app.jar"]
